<script setup lang="ts">defineProps<{value:string|boolean}>();const labels:any={true:'在线',false:'离线',online:'在线',unstable:'不稳定',offline:'离线',disabled:'已停用',ready:'可以开播',blocked:'系统阻断',warning:'存在风险',unknown:'未配置',healthy:'正常',degraded:'延迟',interrupted:'中断',running:'LIVE Studio 运行中',not_running:'未运行',crashed:'异常退出',idle:'未开播',live:'直播中',ended:'已结束',failed:'异常结束',open:'待处理',processing:'处理中',resolved:'已恢复',ignored:'已忽略',checking:'检测中',repairing:'修复中',rechecking:'复检中'};</script>
